insert into ingredient
  (household_id, canonical_name, category, default_unit, status, source, match_text)
select '00000000-0000-0000-0000-0000000000aa', v.canonical_name, v.category, v.default_unit, 'stub', 'seed', v.match_text
  from v
 where not exists (
   select 1 from ingredient i
    where i.household_id = '00000000-0000-0000-0000-0000000000aa'
      and i.match_text = v.match_text and i.deleted_at is null);

